function CountUniqueCharacters(s: string): int
    reads s
    ensures 0 <= result <= |s|
{
    var uniqueChars := set<char>();
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant |uniqueChars| <= i
    {
        uniqueChars := uniqueChars + {s[i]};
        i := i + 1;
    }
    return |uniqueChars|;
}

